settings.code:
{% if collection.handle == 'spare-parts' %}
{% for f in collection.filters %}
{% if f.param_name == 'filter.p.m.custom.spare_parts_type' %}
<style>
/* Filter buttons */
#jalg-parts{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin-bottom:32px}
#jalg-parts a{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:10px 20px;border:1px solid #b8b8b2;background:transparent;color:#000;font:inherit;font-size:16px;line-height:1.4;text-align:center;text-decoration:none}
#jalg-parts a:hover,#jalg-parts a[aria-current]{border-color:#3d5640}
#jalg-parts a[aria-current]{box-shadow:inset 0 0 0 1px #3d5640}
#jalg-parts a:focus-visible{outline:2px solid #3d5640;outline-offset:3px}
.jalg-parts-ready .collection-filter{display:none}
@media(max-width:589px){#jalg-parts{gap:8px;margin-bottom:24px}#jalg-parts a{padding:10px 14px}}
</style>
{% assign sort = collection.sort_by | default: collection.default_sort_by | url_encode %}
<template id="parts-{{ section.id }}">
  <nav id="jalg-parts" aria-label="Filter by part type">
    <a href="{{ collection.url }}?sort_by={{ sort }}"{% if f.active_values.size == 0 %} aria-current="true"{% endif %}>All parts</a>
    {% for v in f.values %}
      <a href="{{ collection.url }}?{{ f.param_name | url_encode }}={{ v.value | url_encode }}&amp;sort_by={{ sort }}"{% if v.active %} aria-current="true"{% endif %}>{{ v.label | escape }}</a>
    {% endfor %}
  </nav>
</template>
{% break %}
{% endif %}
{% endfor %}

<script>
(()=>{
  /* Place buttons above products */
  const place=()=>{
    const t=document.getElementById('parts-{{ section.id }}'),
          p=document.getElementById('CollectionAjaxResult'),
          s=t?.closest('.shopify-section'),
          c=p?.closest('.shopify-section');
    if(!s||!c||s===c)return;
    document.getElementById('jalg-parts')?.remove();
    p.before(t.content.cloneNode(true));
    c.classList.add('jalg-parts-ready');
    s.style.display='none';
  };
  document.readyState==='loading'
    ?document.addEventListener('DOMContentLoaded',place,{once:true})
    :place();
  document.addEventListener('shopify:section:load',place);

  /* Clear filters when changing language or country */
  document.addEventListener('formdata',e=>{
    if(!e.target.matches('form[action$="/localization"]'))return;
    const url=new URL(e.formData.get('return_to')||location.href,location.origin);
    [...url.searchParams.keys()].forEach(key=>{
      if(key.startsWith('filter.')||key==='page')url.searchParams.delete(key);
    });
    e.formData.set('return_to',url.pathname+url.search);
  },true);
})();
</script>
{% endif %}
